// Aplana el payload de Meta en filas manejables.
// Un webhook puede traer estados de entrega o mensajes entrantes.
const out = [];

for (const item of $input.all()) {
  const entries = item.json.body?.entry ?? item.json.entry ?? [];

  for (const entry of entries) {
    for (const change of entry.changes ?? []) {
      const value = change.value ?? {};

      // 1) Actualizaciones de estado de mensajes que enviamos
      for (const st of value.statuses ?? []) {
        out.push({
          json: {
            kind: 'status',
            provider_message_id: st.id,
            status: st.status,          // sent | delivered | read | failed
            error_reason: st.errors?.[0]?.title ?? null,
          },
        });
      }

      // 2) Mensajes entrantes del usuario
      for (const msg of value.messages ?? []) {
        const buttonText =
          msg.button?.text ??
          msg.interactive?.button_reply?.title ??
          null;

        out.push({
          json: {
            kind: 'inbound',
            from: msg.from,
            provider_message_id: msg.context?.id ?? null,
            body: msg.text?.body ?? buttonText ?? '',
            is_affirmative: /^(s[ií]|dale|ok|claro|repetir|s[ií],? repetir)/i.test(
              (msg.text?.body ?? buttonText ?? '').trim()
            ),
          },
        });
      }
    }
  }
}

return out;
